def review_track(change):
    steps = []
    if change.get("new_efin_service"):
        steps.append("자체 보안성심의(제36조) → 시행 후 30일 안 결과보고서")
    if change.get("cloud"):
        steps.append("클라우드 중요도 평가·CSP 평가·업무연속성(제14조의2) → 정보보호위원회 심의·의결")
    if change.get("outsourcing"):
        steps.append("외부주문 보안성검토·정기 보안점검(제60조)")
    net = change.get("internet_from_internal")
    if net:
        if change.get("handles_credit_info"):
            steps.append("망분리 예외 불가 — 구조를 바꾼다(제15조)")
        elif net == "rnd":
            steps.append("연구·개발망 예외: 위험성 평가 + 대체 통제 + 정보보호위원회 승인(제15조)")
        elif net == "saas":
            steps.append("SaaS 예외(시행세칙, 2026-04): 평가받은 SaaS + 단말 보호 + 반기 평가·위원회 보고")
    return steps or ["일반 변경 — 팀 기준 체크리스트만"]

print(review_track({"cloud": True, "internet_from_internal": "saas", "handles_credit_info": True}))

evidence = {
    "분기 계정 권한 검토 기록": ["ISMS-P 2.5", "ISO27001 A.5.18", "PCI DSS 7"],
    "취약점 점검·조치 결과": ["ISMS-P 2.11", "ISO27001 A.8.8", "PCI DSS 11", "감독규정 37조의2"],
    "카드 데이터 흐름도": ["PCI DSS 1", "ISMS-P 1.2"],
}
need = {"ISMS-P", "ISO27001", "PCI DSS"}
for e, ctrls in evidence.items():
    covered = sorted({c.rsplit(" ", 1)[0] for c in ctrls} & need)
    print(f"{e}: {len(ctrls)}개 항목, 인증 {len(covered)}개에 재사용 {covered}")

def maturity(days_between_updates, automated):
    if days_between_updates is None:
        return 1  # 관리 안 함
    if automated and days_between_updates <= 1:
        return 5
    if days_between_updates <= 30:
        return 4
    if days_between_updates <= 365:
        return 3  # 인증 심사 때만 맞춘다
    return 2

assets = {"사용자": (1, True), "단말": (1, True), "네트워크": (90, False),
          "애플리케이션·워크로드": (365, False), "데이터": (None, False)}
scores = {k: maturity(*v) for k, v in assets.items()}
print(scores, "평균", round(sum(scores.values()) / len(scores), 1))
print("다음 해 일감:", [k for k, v in scores.items() if v <= 2])
